                    // `Body{ .x = 1 }` names its type; a JS object literal cannot
                    // and does not need to.
                    if (!host_is_js) elements.appendSlice(allocator, type_name) catch unreachable;
                    elements.appendSlice(allocator, "{ ") catch unreachable;
                    elements.appendSlice(allocator, fields) catch unreachable;
                    elements.appendSlice(allocator, " }") catch unreachable;
