            .host_line = ast.HostLine{
                .content = allocator.dupe(u8, static_decl) catch unreachable,
                .location = flow.location,
                .module = allocator.dupe(u8, home_module) catch unreachable,
            },
        };

        // PERSISTENT WORKER POOL (Zig, store mode): one module-scope pool,
        // lazily created on first use and REUSED across every store-kernel
        // call and frame — thread spawn cost is paid once per process, not
        // once per kernel run. Emitted once per program (dedup scan so N
        // store kernels share one pool). JavaScript is single-threaded this
        // rung and needs no pool.
        const pool_item = if (host_is_js or !is_store_mode) null else blk: {
