                fn scan(items: []const ast.Item) bool {
                    for (items) |it| {
                        if (it == .host_line) {
                            if (std.mem.indexOf(u8, it.host_line.content, "__koru_pool_ensure") != null) return true;
                        }
                        if (it == .module_decl) {
