            }
        }
        return null;
    }
}.call;

const countInitElements = struct {
    fn call(text: []const u8) ?usize {
        var depth: i32 = 0;
        var count: usize = 0;
        var in_string: bool = false;
        var escaped: bool = false;

        for (text) |c| {
            if (in_string) {
                if (escaped) {
                    escaped = false;
                    continue;
                }
                if (c == '\\') {
                    escaped = true;
                    continue;
                }
                if (c == '"') {
                    in_string = false;
                }
                continue;
            } else if (c == '"') {
                in_string = true;
                continue;
            }

            if (c == '{') {
                depth += 1;
            } else if (c == '}') {
                if (depth == 1) {
                    count += 1;
                }
                depth -= 1;
            }
        }

        if (count > 0) return count;
        return null;
    }
}.call;

